// "Common mistakes & exam traps" questions for domains B–F (domain A traps live in communication.mjs).
// They are part of the CCI-proportioned core bank and carry the tag 'trap' so the Traps quiz can drill them.
import { make, SRC } from './helpers.mjs';
const b = make('B'), c = make('C'), d = make('D'), e = make('E'), f = make('F');
const T = { tags: ['trap'] };
const TI = img => ({ tags: ['trap'], image: img });
const TM = { tags: ['trap', 'medication'] };
const TC = img => ({ tags: ['trap', 'calculation'], ...(img ? { image: img } : {}) });

export default [
// ===================== B: Resting ECG (22) =====================
b.M('Troubleshooting', 2, 'TRAP: With the RA and LA electrodes reversed, which limb lead is UNCHANGED?', 'aVF', ['Lead I', 'aVR', 'aVL'], 'Swapping the arm electrodes inverts lead I, swaps II with III and swaps aVR with aVL. aVF uses the left leg against the average of both arms, so it is unaffected.', SRC.AHA_STD, T),
b.M('Troubleshooting', 2, 'TRAP: An almost flat line (very low voltage) in lead II only is a classic sign of which reversal?', 'Right arm and right leg (RA–RL) reversal', ['Left arm and left leg reversal', 'V1 and V2 reversal', 'Right arm and left arm reversal'], 'When the RA electrode is on the right leg, lead II records between the two legs, which are electrically almost identical, so it is nearly flat. Arm reversal inverts lead I instead, and LA–LL reversal is subtle.', SRC.AHA_STD, T),
b.M('Troubleshooting', 3, 'TRAP: Which limb lead reversal is the hardest to spot because the tracing can still look "normal"?', 'Left arm and left leg (LA–LL) reversal', ['Right arm and left arm reversal', 'Right arm and right leg reversal', 'Precordial leads V1 and V6 reversed'], 'LA–LL reversal swaps I with II and aVL with aVF and inverts III, which often still looks plausible; a clue is a P wave taller in I than in II. RA–LA reversal inverts lead I, and RA–RL flattens lead II, which are easier to see.', SRC.AHA_STD, TI('12lead-rev_lall-1')),
b.M('Troubleshooting', 2, 'TRAP: Swapping only the right leg (RL) and left leg (LL) electrodes usually:', 'Causes little or no change, because RL is only the ground/reference', ['Inverts every limb lead', 'Flattens lead I', 'Mimics an inferior MI in every case'], 'The RL electrode acts as a ground, and the two legs are electrically similar, so the tracing is essentially unchanged. Arm reversals and RA–RL reversal produce the obvious changes.', SRC.AHA_STD, T),
b.M('Calibration & paper', 2, 'TRAP: A tracing was accidentally recorded at 50 mm/s. Compared with 25 mm/s, the complexes will look:', 'Twice as wide, so intervals look longer and the rate looks slower unless you correct for speed', ['Twice as tall', 'Exactly the same', 'Half as wide'], 'Doubling paper speed spreads each beat over twice as many boxes, so a 0.16 s PR spans 8 small boxes instead of 4. Height depends on gain (mm/mV), not speed.', SRC.AHA_STD, T),
b.M('Calibration & paper', 2, 'TRAP: The calibration pulse at the start of a tracing is 5 mm tall. This means:', 'The ECG is at half standard (5 mm/mV), so all voltages are half their true size', ['The ECG is at double standard', 'The ECG is at normal standard', 'The paper speed is 50 mm/s'], 'Normal standard is 10 mm = 1 mV. A 5 mm pulse means half standard, so a 15 mm R wave is really 30 mm at standard—important for LVH criteria. Calibration pulse height does not tell you paper speed.', SRC.AHA_STD, T),
b.M('12-lead procedure', 2, 'TRAP: V1 and V2 placed too HIGH (2nd or 3rd intercostal space) can create:', 'An rSr\' pattern and T-wave changes that mimic RBBB or septal abnormalities', ['A delta wave', 'A short QT interval', 'Peaked T waves of hyperkalemia'], 'High placement changes the angle at which V1–V2 view the heart and can produce an rSr\' and inverted P/T waves, leading to false diagnoses. Always count down to the 4th intercostal space.', SRC.AHA_STD, T),
b.M('12-lead procedure', 1, 'TRAP: Which description of V1 and V2 is CORRECT?', 'V1: 4th ICS right sternal border; V2: 4th ICS left sternal border', ['V1: 4th ICS left sternal border; V2: 4th ICS right sternal border', 'V1: 5th ICS right midclavicular line; V2: 5th ICS left midclavicular line', 'V1 and V2 both at the 2nd ICS'], 'V1 is to the patient\'s RIGHT of the sternum and V2 to the LEFT, both in the 4th intercostal space. Swapping them or placing them at the 2nd ICS is a common placement error.', SRC.AHA_STD, T),
b.M('12-lead procedure', 2, 'TRAP: The most reliable way to find the 4th intercostal space is to:', 'Find the sternal angle (angle of Louis), slide to the 2nd rib, then count down to the space below the 4th rib', ['Measure 4 inches down from the clavicle', 'Use the nipple line in every patient', 'Start counting from the xiphoid upward'], 'The sternal angle marks the 2nd rib; the space below it is the 2nd ICS, and counting down from there finds the 4th ICS. Nipple position and fixed distances vary widely between patients.', SRC.AHA_STD, T),
b.M('Troubleshooting', 2, 'TRAP: An irregular, jagged baseline that varies between beats is somatic tremor. A perfectly regular, uniform "fuzz" is:', '60-cycle (AC) interference', ['Atrial fibrillation', 'Wandering baseline', 'Ventricular flutter'], 'Muscle tremor is irregular and changes with patient movement; AC interference is uniform at 60 cycles per second. Atrial fibrillation waves are irregular and the R–R interval is irregularly irregular.', SRC.BOOTH, TI('art_60hz-6')),
b.M('Troubleshooting', 2, 'TRAP: A slowly drifting baseline that rises and falls with each breath is usually fixed by:', 'Rechecking skin prep and electrode contact, and having the patient breathe quietly', ['Turning on the 60 Hz notch filter', 'Increasing the gain to 20 mm/mV', 'Changing paper speed to 50 mm/s'], 'Wandering baseline comes from respiration, lotion/oils or poor electrode contact. The notch filter only removes power-line noise, and gain or speed changes do not fix contact problems.', SRC.BOOTH, TI('art_wander-6')),
b.M('Supplies', 2, 'TRAP: For a diagnostic 12-lead, the AHA recommends a low-frequency (high-pass) cutoff of about 0.05 Hz because higher "monitor mode" cutoffs can:', 'Distort the ST segment and create false ST elevation or depression', ['Remove the P waves entirely', 'Speed up the heart rate', 'Increase QRS duration'], 'Monitor filters (e.g., 0.5 Hz) reduce baseline wander but can artificially shift the ST segment. AHA recommends 0.05 Hz (or 0.67 Hz only with special zero-phase digital filters) for diagnostic ECGs.', SRC.AHA_STD, T),
b.M('Supplies', 3, 'TRAP: What high-frequency (low-pass) cutoff does the AHA recommend for adult diagnostic 12-lead ECGs?', 'At least 150 Hz', ['40 Hz', '25 Hz', '10 Hz'], 'A 150 Hz upper limit (250 Hz for children) preserves sharp QRS detail and pacing spikes. A 40 Hz monitor filter smooths the tracing but can reduce QRS amplitude and hide notching.', SRC.AHA_STD, T),
b.M('Modified ECG', 2, 'TRAP: For a suspected right-ventricular infarction, a "right-sided ECG" changes:', 'Only the chest leads (V3R–V6R mirrored on the right); limb leads stay in standard position', ['Only the limb leads', 'Both limb leads and chest leads, as for dextrocardia', 'Nothing—V4R is printed automatically'], 'Right-sided leads mirror the precordial electrodes on the right chest; the limb leads stay normal. For dextrocardia, the arm electrodes are also reversed. Machines label leads but do not move electrodes for you.', SRC.AHA_STD, T),
b.M('Modified ECG', 2, 'TRAP: Posterior leads V7, V8 and V9 are placed:', 'On the left back at the same horizontal level as V6', ['On the right chest at the 4th ICS', 'On the left back one rib space above V6', 'Over the spine at the level of the scapular spine'], 'V7 (posterior axillary line), V8 (tip of the scapula / mid-scapular line) and V9 (left paraspinal border) continue the V6 horizontal line around the back. They are not on the right chest or placed higher.', SRC.AHA_STD, T),
b.M('Modified ECG', 2, 'TRAP: V3R is placed:', 'Midway between V1 and V4R', ['At the 4th ICS left sternal border', 'At the 5th ICS right midaxillary line', 'Directly over the xiphoid process'], 'V4R is at the 5th ICS right midclavicular line, and V3R lies halfway between V1 and V4R, mirroring V3. The left sternal border is the V2 position.', SRC.AHA_STD, T),
b.M('Lead systems', 2, 'TRAP: In lead III, the NEGATIVE electrode is the:', 'Left arm', ['Right arm', 'Left leg', 'Right leg'], 'Lead I: RA (−) to LA (+). Lead II: RA (−) to LL (+). Lead III: LA (−) to LL (+). The right leg is the ground electrode and is not part of any bipolar lead.', SRC.DUBIN, T),
b.M('Lead systems', 2, 'TRAP: Einthoven\'s law states that, at any instant:', 'Lead I + Lead III = Lead II', ['Lead I + Lead II = Lead III', 'aVR + aVL = aVF', 'V1 + V6 = Lead II'], 'Because of how the bipolar leads are built, the voltage in lead II equals the sum of leads I and III. Machines use this relationship, and it helps detect limb lead errors.', SRC.DUBIN, T),
b.M('Lead systems', 1, 'TRAP: Which leads are the augmented unipolar limb leads?', 'aVR, aVL, aVF', ['I, II, III', 'V1, V2, V3', 'V4R, V5R, V6R'], 'The augmented leads compare one limb electrode with the average of the other two. Leads I–III are bipolar, and V leads are precordial (chest) leads.', SRC.DUBIN, T),
b.M('Calibration & paper', 2, 'TRAP: On a standard 3 × 4 printout, each lead column represents about:', '2.5 seconds of the 10-second recording', ['10 seconds per lead', '1 second per lead', '6 seconds per lead'], 'The machine records all leads simultaneously for 10 seconds but prints four consecutive 2.5-second windows across the page; the rhythm strip at the bottom shows the full 10 seconds.', SRC.AHA_STD, T),
b.M('Supplies', 2, 'TRAP: In the IEC (European) color code, the RED electrode goes on the:', 'Right arm', ['Left leg', 'Left arm', 'Right leg'], 'IEC: RA red, LA yellow, LL green, RL black. AHA (U.S.): RA white, LA black, LL red, RL green. Mixing the systems is a common cause of limb lead reversal.', SRC.AHA_STD, T),
b.M('12-lead procedure', 2, 'TRAP: Placing limb electrodes on the torso (Mason-Likar) for a resting 12-lead:', 'Can change the tracing (axis and limb-lead voltages), so it should be labeled if used', ['Has no effect on the ECG', 'Is the standard for every resting ECG', 'Only affects the precordial leads'], 'Torso placement is standard for exercise testing but alters limb-lead appearance, so resting ECGs should use distal limb positions or be clearly labeled. It does not leave the tracing identical.', SRC.AHA_STD, T),

// ===================== C: Analyzing 12-lead (30) =====================
c.M('Ischemia & infarction', 2, 'TRAP: ST elevation in V1–V4 most likely involves which artery?', 'Left anterior descending (LAD)', ['Right coronary artery', 'Left circumflex', 'Posterior descending artery'], 'V1–V2 (septal) and V3–V4 (anterior) face LAD territory. The RCA is usually inferior (II, III, aVF) and the circumflex lateral (I, aVL, V5–V6).', SRC.AHA_ISCH, TI('12lead-anterior-3')),
c.M('Ischemia & infarction', 2, 'TRAP: This tracing shows ST elevation in II, III and aVF. The ST depression in aVL is best explained as:', 'Reciprocal change supporting an acute inferior STEMI', ['A separate lateral STEMI', 'Normal variant', 'Lead reversal'], 'aVL faces roughly opposite the inferior wall, so inferior injury produces mirror-image ST depression there. Reciprocal depression strengthens the diagnosis of STEMI rather than indicating a second infarct.', SRC.AHA_ISCH, TI('12lead-inferior-2')),
c.M('Ischemia & infarction', 3, 'TRAP: ST depression with tall R waves in V1–V3 should make you think of:', 'A posterior wall MI — confirm with posterior leads V7–V9', ['Normal septal depolarization', 'Anterior wall ischemia only', 'Left bundle branch block'], 'No standard lead faces the posterior wall, so posterior injury appears as the mirror image in V1–V3 (ST depression, tall R). Recording V7–V9 can show the ST elevation directly.', SRC.AHA_ISCH, TI('12lead-posterior-1')),
c.M('Ischemia & infarction', 3, 'TRAP: Which finding favors pericarditis rather than STEMI?', 'Diffuse concave ST elevation in many leads with PR depression and no reciprocal ST depression (except aVR/V1)', ['ST elevation limited to II, III and aVF with reciprocal depression in aVL', 'New Q waves in V1–V4', 'ST elevation in one coronary territory with convex shape'], 'Pericarditis inflames the whole epicardium, so ST elevation is widespread and not limited to one artery, often with PR depression. Territorial ST elevation with reciprocal depression points to STEMI.', SRC.AHA_ISCH, T),
c.M('Bundle branch block', 2, 'TRAP: In LBBB, ST segments and T waves that point OPPOSITE to the main QRS deflection are:', 'An expected secondary repolarization change (discordance), not by themselves a sign of ischemia', ['Always a sign of acute MI', 'A sign of hyperkalemia', 'Caused by lead reversal'], 'In LBBB, repolarization follows abnormal depolarization, so ST-T discordance is normal for the block. Concordant ST changes (same direction as QRS) are more concerning.', SRC.AHA_BBB, TI('12lead-lbbb-3')),
c.M('Bundle branch block', 2, 'TRAP: In an adult, an RBBB pattern with QRS 0.11 s (110 ms) is called:', 'Incomplete RBBB', ['Complete RBBB', 'LBBB', 'Normal QRS with no conduction delay'], 'AHA criteria: complete RBBB requires QRS ≥ 120 ms; the same pattern at 110–119 ms is incomplete RBBB. LBBB has a different morphology (QS in V1, broad R in V6).', SRC.AHA_BBB, T),
c.M('Axis', 2, 'TRAP: On an exam, "LAD" in a question about leads I and aVF most likely means:', 'Left axis deviation', ['Left anterior descending artery', 'Left atrial dilation', 'Late atrial depolarization'], 'The same abbreviation is used for left axis deviation and the left anterior descending artery. Read the context: lead I/aVF polarity questions are about axis; ST elevation in V1–V4 questions are about the artery.', SRC.DUBIN, T),
c.M('Axis', 3, 'TRAP: Lead I is positive and aVF is negative. Before calling left axis deviation you should check:', 'Lead II — if II is positive, the axis is still normal (0° to −30°)', ['Lead V1', 'aVR only', 'The PR interval'], 'Axis between 0° and −30° makes aVF slightly negative but is still normal; lead II stays positive. If lead II is negative too, the axis is beyond −30° (left axis deviation).', SRC.DUBIN, TI('12lead-lad-2')),
c.S('Axis', 2, 'TRAP: Which conditions cause LEFT axis deviation? (Select two.)', ['Left anterior fascicular block', 'Inferior wall MI'], ['Right ventricular hypertrophy', 'Left posterior fascicular block', 'COPD'], 'LAFB and inferior MI shift the frontal axis leftward/superiorly. RVH, LPFB and COPD typically shift it to the right.', SRC.AHA_BBB, T),
c.S('Axis', 2, 'TRAP: Which conditions cause RIGHT axis deviation? (Select two.)', ['Right ventricular hypertrophy', 'Left posterior fascicular block'], ['Left anterior fascicular block', 'Left ventricular hypertrophy', 'Inferior wall MI'], 'RVH and LPFB move the axis rightward (+90° to +180°). LAFB, LVH and inferior MI are associated with left axis deviation.', SRC.AHA_BBB, T),
c.M('Ischemia & infarction', 2, 'TRAP: Small, narrow q waves in leads I, aVL, V5 and V6 are usually:', 'Normal septal q waves', ['Pathologic Q waves of lateral MI', 'A sign of RBBB', 'Artifact'], 'Normal left-to-right septal depolarization produces small q waves (< 0.04 s) in the lateral leads. Pathologic Q waves are ≥ 0.04 s wide or ≥ 25% of the R wave height.', SRC.AHA_ISCH, T),
c.M('Ischemia & infarction', 3, 'TRAP: Which T waves are typical of hyperkalemia rather than hyperacute STEMI?', 'Tall, narrow-based, symmetric "tented" T waves across many leads', ['Broad, bulky T waves in one coronary territory with ST elevation', 'Flat T waves with prominent U waves', 'Inverted T waves in V1 only'], 'Hyperkalemia gives peaked, pinched T waves in many leads regardless of territory. Hyperacute T waves of early STEMI are broad-based and localized to the injured territory. Flat T waves with U waves suggest hypokalemia.', SRC.AHA_QT, TI('12lead-hyperk-2')),
c.M('Ischemia & infarction', 2, 'TRAP: ST elevation or depression is measured at the:', 'J point, compared with the baseline (PR/TP segment)', ['Peak of the T wave', 'Peak of the R wave', 'Start of the P wave'], 'The J point is where the QRS ends and the ST segment begins; its height relative to the isoelectric baseline defines ST deviation. Measuring at the T wave or R wave peak gives meaningless values.', SRC.UDMI, T),
c.M('Ischemia & infarction', 3, 'TRAP: For a woman, the STEMI threshold for new ST elevation in V2–V3 is:', '≥ 1.5 mm', ['≥ 2.5 mm', '≥ 0.5 mm', '≥ 4 mm'], 'The Universal Definition uses ≥ 1.5 mm in V2–V3 for women, ≥ 2 mm for men ≥ 40 and ≥ 2.5 mm for men < 40; other leads use ≥ 1 mm in two contiguous leads. Using the men\'s threshold can miss MI in women.', SRC.UDMI, T),
c.M('Ischemia & infarction', 3, 'TRAP: A healthy 22-year-old has concave ST elevation with J-point notching in V2–V5, no reciprocal changes and no symptoms. This most likely represents:', 'Early repolarization (a normal variant)', ['Acute anterior STEMI', 'Hyperkalemia', 'Posterior MI'], 'Benign early repolarization is common in young, athletic people and lacks reciprocal depression and evolution. Still report it, but STEMI usually has territorial, often convex elevation with reciprocal changes and symptoms.', SRC.AHA_QT, T),
c.M('Ischemia & infarction', 3, 'TRAP: A pain-free patient has deep, symmetric T-wave inversions in V2–V3 after recent chest pain. This pattern (Wellens) suggests:', 'Critical stenosis of the proximal LAD — report promptly; stress testing may be dangerous', ['Normal juvenile T waves', 'Digoxin effect', 'Right bundle branch block'], 'Wellens syndrome T waves appear in the pain-free period and warn of an impending anterior MI. Juvenile T inversions are usually in V1–V3 of children, and digoxin causes scooped ST depression.', SRC.AHA_ISCH, T),
c.S('Hypertrophy', 3, 'TRAP: Which conditions can cause a TALL R wave in V1? (Select three.)', ['Right bundle branch block', 'Posterior wall MI', 'Right ventricular hypertrophy'], ['Left bundle branch block', 'Hypokalemia', 'Pericarditis'], 'RBBB (R\'), posterior MI (mirror image of posterior Q waves) and RVH all produce a dominant R in V1. LBBB produces a deep QS in V1.', SRC.AHA_LVH, T),
c.M('Hypertrophy', 2, 'TRAP: Tall, peaked P waves (≥ 2.5 mm in lead II) suggest:', 'Right atrial enlargement (P pulmonale)', ['Left atrial enlargement (P mitrale)', 'Hyperkalemia', 'First-degree AV block'], 'P pulmonale (think lung disease → right heart) is tall and peaked. P mitrale (think mitral stenosis → left atrium) is wide (≥ 0.12 s) and notched.', SRC.AHA_LVH, T),
c.M('Hypertrophy', 2, 'TRAP: Lateral ST depression and asymmetric T inversion in a tracing with very tall voltage (as shown) most likely represent:', 'LVH with "strain" (secondary repolarization change)', ['Acute lateral STEMI', 'Pericarditis', 'Hypocalcemia'], 'Strain is asymmetric ST depression/T inversion in leads with tall R waves (V5–V6, I, aVL) due to the thick LV. It is not ST elevation, and it is not diffuse like pericarditis.', SRC.AHA_LVH, TI('12lead-lvh-2')),
c.M('Ischemia & infarction', 2, 'TRAP: Prominent U waves and flattened T waves most suggest:', 'Hypokalemia', ['Hyperkalemia', 'Hypercalcemia', 'Acute STEMI'], 'Low potassium flattens T waves and makes U waves prominent; it also prolongs the QU interval. High potassium causes peaked T waves, and calcium mainly changes the QT length.', SRC.AHA_QT, T),
c.M('Ischemia & infarction', 2, 'TRAP: A SHORT QT interval is associated with:', 'Hypercalcemia (and digoxin)', ['Hypocalcemia', 'Hypokalemia', 'Amiodarone'], 'High calcium shortens the ST segment and QT; digoxin also shortens QT. Low calcium lengthens the ST segment and QT, and amiodarone prolongs QT.', SRC.AHA_QT, T),
c.M('Ischemia & infarction', 3, 'TRAP: ST elevation in aVR with widespread ST depression in many other leads suggests:', 'Left main or multivessel (diffuse subendocardial) ischemia — report immediately', ['A normal finding because aVR is always abnormal', 'Isolated right arm lead reversal', 'Early repolarization'], 'ST elevation in aVR with diffuse ST depression is a recognized warning pattern for left main or severe three-vessel disease. aVR changes should not be ignored.', SRC.AHA_ISCH, T),
c.M('Ischemia & infarction', 2, 'TRAP: Which pair of leads is NOT contiguous (they view opposite regions)?', 'III and aVL', ['II and aVF', 'V2 and V3', 'I and aVL'], 'Contiguous leads view neighboring regions: II, III, aVF (inferior); I and aVL (high lateral); V1–V6 in sequence. III and aVL face roughly opposite directions, so they show reciprocal changes.', SRC.AHA_ISCH, T),
c.M('Ischemia & infarction', 2, 'TRAP: Changes in V1–V4 PLUS I and aVL (and often V5–V6) describe which MI pattern?', 'Extensive anterior (anterolateral) MI, usually proximal LAD', ['Isolated inferior MI', 'Posterior MI', 'Right ventricular MI'], 'Anterior leads plus lateral leads indicate a large LAD territory including diagonal branches. Inferior MI uses II, III, aVF; posterior MI shows mirror changes in V1–V3.', SRC.AHA_ISCH, TI('12lead-anterolateral-2')),
c.M('Anatomy & physiology', 2, 'TRAP: Which lead normally shows negative P, QRS and T waves because it "looks" at the heart from the right shoulder?', 'aVR', ['aVF', 'Lead II', 'V6'], 'The mean electrical vector travels away from the right shoulder, so aVR is normally negative. An upright aVR with an inverted lead I suggests arm lead reversal (or dextrocardia).', SRC.AHA_STD, T),
c.M('Anatomy & physiology', 2, 'TRAP: Poor R-wave progression across V1–V4 can be caused by:', 'Chest electrodes placed too high, or a prior anterior MI', ['Normal paper speed', 'Hyperkalemia only', 'A correct 4th ICS placement'], 'R waves normally grow from V1 to V4–V5 with the transition near V3–V4. Misplaced (high) V leads and old anterior infarction both reduce anterior R waves, so check placement before reporting.', SRC.AHA_STD, T),
c.M('Axis', 3, 'TRAP: Left anterior fascicular block is suggested by:', 'Left axis deviation of −45° or more with qR in aVL and rS in II, III, aVF', ['Right axis deviation with rS in lead I', 'QRS ≥ 0.12 s with rSR\' in V1 only', 'Short PR with a delta wave'], 'LAFB shifts the axis superiorly to about −45° or beyond with characteristic qR/rS patterns; the QRS stays under 0.12 s. Right axis with rS in I suggests LPFB.', SRC.AHA_BBB, T),
c.M('Anatomy & physiology', 3, 'TRAP: A short PR interval (< 0.12 s), a slurred upstroke (delta wave) and a slightly wide QRS suggest:', 'Wolff-Parkinson-White (ventricular pre-excitation)', ['First-degree AV block', 'LBBB', 'Junctional rhythm with normal QRS'], 'An accessory pathway bypasses the AV node, so the ventricles start depolarizing early (short PR, delta wave). First-degree block has a long PR, and junctional rhythms have abnormal P waves without delta waves.', SRC.MARRIOTT, T),
c.M('Anatomy & physiology', 2, 'TRAP: Where is the normal precordial R/S transition zone (R about equal to S)?', 'Around V3–V4', ['V1', 'V6', 'aVR'], 'The QRS changes from mostly negative in V1 to mostly positive in V5–V6, with the transition near V3–V4. An early or late transition may indicate rotation, misplacement or disease.', SRC.AHA_STD, T),
c.M('Ischemia & infarction', 2, 'TRAP: Septal leads are V1–V2. Which leads are the ANTERIOR leads?', 'V3–V4', ['V5–V6', 'II, III, aVF', 'I and aVL'], 'V1–V2 septal, V3–V4 anterior, V5–V6 low lateral, I/aVL high lateral, II/III/aVF inferior. Mixing up these groups is one of the most common exam mistakes.', SRC.AHA_ISCH, T),

// ===================== D: Stress (18) =====================
d.M('Protocols', 2, 'TRAP: Stage 1 of the standard Bruce protocol is:', '1.7 mph at a 10% grade for 3 minutes', ['1.7 mph at 0% grade', '2.5 mph at 12% grade', '3.4 mph at 14% grade'], 'Bruce stage 1 is 1.7 mph/10%; stage 2 is 2.5 mph/12% and stage 3 is 3.4 mph/14%. The Modified Bruce adds two easier 3-minute stages at 1.7 mph and 0% then 5% grade.', SRC.ACC_EX, T),
d.M('Protocols', 2, 'TRAP: The "target heart rate" commonly used for an adequate exercise test is:', '85% of the age-predicted maximum (220 − age)', ['85 beats per minute', '220 beats per minute minus 85', '100% of resting heart rate'], 'Reaching ≥ 85% of age-predicted maximum heart rate is a common marker of an adequate test. It is a percentage of predicted maximum, not 85 bpm.', SRC.AHA_EX, T),
d.M('Protocols', 2, 'TRAP: What is 85% of the age-predicted maximum heart rate for a 60-year-old?', '136 bpm', ['160 bpm', '145 bpm', '119 bpm'], '220 − 60 = 160 bpm predicted maximum; 160 × 0.85 = 136 bpm. 160 is the full predicted maximum, not the 85% target.', SRC.AHA_EX, TC()),
d.M('Protocols', 3, 'TRAP: What is 85% of the age-predicted maximum heart rate for a 45-year-old?', '149 bpm', ['175 bpm', '135 bpm', '158 bpm'], '220 − 45 = 175; 175 × 0.85 = 148.75 ≈ 149 bpm. 175 is the predicted maximum, and the others are miscalculations.', SRC.AHA_EX, TC()),
d.M('Endpoints', 3, 'TRAP: During exercise, which blood pressure response is an indication to STOP the test?', 'A drop in systolic BP of more than 10 mm Hg from baseline despite increasing workload, with other evidence of ischemia', ['Systolic BP rises from 130 to 170 mm Hg', 'Diastolic BP stays the same or falls slightly', 'Systolic BP rises 10 mm Hg per stage'], 'Normally systolic BP rises with workload while diastolic stays the same or falls slightly. A falling systolic pressure with increasing work suggests severe ischemia or LV dysfunction and is an indication to stop.', SRC.AHA_EX, T),
d.M('Endpoints', 3, 'TRAP: The AHA lists which hypertensive response as a RELATIVE indication to stop exercise?', 'Systolic BP > 250 mm Hg and/or diastolic BP > 115 mm Hg', ['Systolic BP > 160 mm Hg', 'Diastolic BP > 85 mm Hg', 'Any rise in systolic BP'], 'Marked hypertensive response (SBP > 250 or DBP > 115) is a relative indication to stop. A systolic rise to 160 is a normal exercise response.', SRC.AHA_EX, T),
d.M('Contraindications', 2, 'TRAP: Which is an ABSOLUTE contraindication to exercise stress testing?', 'Acute myocardial infarction within 2 days', ['Asymptomatic severe aortic stenosis', 'Known left main disease', 'Resting hypertension of 170/100'], 'AHA absolute contraindications include acute MI within 2 days, unstable angina not yet stabilized, symptomatic severe aortic stenosis, uncontrolled symptomatic arrhythmias, decompensated heart failure, acute PE, acute myocarditis/pericarditis and acute aortic dissection. The other choices are relative contraindications.', SRC.AHA_EX, T),
d.M('Contraindications', 3, 'TRAP: Severe aortic stenosis is an ABSOLUTE contraindication to exercise testing when it is:', 'Symptomatic', ['Asymptomatic', 'Mild', 'Already repaired'], 'Symptomatic severe aortic stenosis is an absolute contraindication; asymptomatic severe AS is a relative contraindication that a physician may still evaluate carefully.', SRC.AHA_EX, T),
d.M('Endpoints', 2, 'TRAP: Which ECG finding during exercise is an ABSOLUTE indication to stop?', 'ST elevation ≥ 1 mm in leads without pre-existing Q waves (other than V1 or aVR)', ['1 mm upsloping ST depression', 'Isolated unifocal PVCs', 'Heart rate reaching 85% of predicted'], 'New ST elevation in leads without Q waves indicates transmural ischemia and requires stopping. Upsloping depression is less specific, occasional PVCs are common, and reaching target heart rate is not by itself a reason to stop.', SRC.AHA_EX, T),
d.M('Endpoints', 2, 'TRAP: Which ST change is the classic "positive" (ischemic) exercise response?', '≥ 1 mm horizontal or downsloping ST depression about 80 ms after the J point', ['J-point depression with rapidly upsloping ST', 'T-wave peaking at peak exercise', 'Shortening of the QT interval'], 'Horizontal or downsloping depression of ≥ 1 mm is the standard criterion. Rapid upsloping J-point depression is common and normal, and QT shortening is the normal response to faster rates.', SRC.AHA_EX, T),
d.M('Endpoints', 2, 'TRAP: The patient asks to stop the treadmill because they are exhausted. You should:', 'Stop the test — the patient\'s desire to stop is an absolute indication', ['Encourage them to keep going until 85% target HR', 'Increase the speed to finish the stage', 'Ignore it unless ST changes appear'], 'A patient\'s request to stop is an absolute endpoint in AHA standards. Encouragement is fine early, but you never force a patient to continue against their wishes.', SRC.AHA_EX, { tags: ['trap', 'scenario'] }),
d.M('Pharmacologic & nuclear', 2, 'TRAP: The effects of adenosine or regadenoson are reversed with:', 'Aminophylline', ['Atropine', 'Dobutamine', 'Nitroglycerin'], 'Aminophylline blocks adenosine receptors and reverses vasodilator side effects. Atropine raises heart rate, dobutamine is itself a stress agent, and nitroglycerin is used for angina.', SRC.ASNC, TM),
d.M('Pharmacologic & nuclear', 2, 'TRAP: Dobutamine-induced ischemia or arrhythmia is reversed with:', 'A short-acting IV beta blocker (e.g., esmolol or metoprolol)', ['Aminophylline', 'Adenosine', 'Caffeine'], 'Dobutamine is a beta-1 agonist, so a beta blocker counteracts it. Aminophylline reverses adenosine/regadenoson, not dobutamine.', SRC.ASNC, TM),
d.M('Pharmacologic & nuclear', 2, 'TRAP: Before an adenosine or regadenoson stress test, patients must avoid caffeine because caffeine:', 'Blocks adenosine receptors and can make the test falsely negative', ['Increases the effect of adenosine', 'Causes hyperkalemia', 'Prolongs the QT interval'], 'Caffeine and other methylxanthines are adenosine receptor antagonists. ASNC advises holding caffeine for at least 12 hours before vasodilator stress.', SRC.ASNC, T),
d.M('Stress equipment', 2, 'TRAP: A patient grips the treadmill handrails tightly throughout the test. This will:', 'Overestimate exercise capacity (METs) and add arm-muscle artifact', ['Underestimate exercise capacity', 'Have no effect on the results', 'Lower the heart rate'], 'Leaning on the rails reduces the work of walking, so predicted METs from speed and grade are too high; muscle tension also adds artifact. Light balance-touching is acceptable.', SRC.AHA_EX, T),
d.M('Protocols', 1, 'TRAP: One MET (metabolic equivalent) equals an oxygen uptake of about:', '3.5 mL O₂/kg/min', ['35 mL O₂/kg/min', '1 L O₂/min', '0.35 mL O₂/kg/min'], 'One MET is the approximate resting oxygen consumption, 3.5 mL/kg/min. Exercise capacity is expressed as multiples of this value.', SRC.AHA_EX, T),
d.M('Stress patient care', 2, 'TRAP: The original Borg rating of perceived exertion (RPE) scale runs from:', '6 to 20', ['0 to 10', '1 to 5', '0 to 100'], 'The classic Borg scale is 6–20 (roughly heart rate ÷ 10 in young adults). The 0–10 scale is the separate Borg CR10 category-ratio scale, often used for dyspnea or angina.', SRC.AHA_EX, T),
d.M('Stress patient care', 2, 'TRAP: A patient on a beta blocker fails to reach the target heart rate. The best explanation is:', 'Beta blockers blunt the heart-rate response to exercise', ['The treadmill is miscalibrated', 'Beta blockers increase heart rate', 'The patient is not trying'], 'Beta blockers limit chronotropic response, which can make a test non-diagnostic; they are held before testing only on physician order. Do not stop or change medications yourself.', SRC.AHA_EX, TM),

// ===================== E: Ambulatory (6) =====================
e.M('Holter basics', 2, 'TRAP: A patient asks if they must press the Holter event button to make it record. The correct answer is:', 'No — a Holter records continuously; the button only marks the time of symptoms', ['Yes — it records only when pressed', 'Yes — press it every hour', 'No — the Holter only records at night'], 'Holter monitors record every beat for the whole wear period (commonly 24–48 hours). The event button and diary let the reader correlate symptoms with the rhythm. Patient-activated recording is a feature of event recorders.', SRC.ISHNE, T),
e.M('Holter basics', 2, 'TRAP: A looping event recorder differs from a post-event (symptom) recorder because it:', 'Continuously saves a rolling memory, so it can store the rhythm from before and after the button press', ['Records only after the patient presses the button', 'Must be implanted surgically', 'Records only 60 seconds per day'], 'Loop recorders keep overwriting a short buffer, so pressing the button saves the moments before symptoms began. A post-event recorder captures only what happens after it is applied or activated.', SRC.ISHNE, T),
e.M('Holter education', 2, 'TRAP: The most important item for the patient to write in the Holter diary is:', 'The time and description of any symptoms and activities', ['Their blood type', 'Every meal eaten in detail', 'The serial number of the device'], 'Correlating symptom times with the recording is the main purpose of the diary. Activities such as exercise, sleep and medication times also help the reader.', SRC.ISHNE, T),
e.M('Holter troubleshooting', 2, 'TRAP: A telemetry alarm shows "asystole." What should you do FIRST?', 'Check the patient (responsiveness, pulse) — a loose lead can look like asystole', ['Assume a lead fell off and silence the alarm', 'Print the strip and file it', 'Wait to see whether it resolves'], 'Always assess the patient before blaming the equipment; if the patient is unresponsive and pulseless, start CPR. If the patient is fine, fix the lead. Silencing an alarm without checking is a dangerous error.', SRC.AHA_AMB, { tags: ['trap', 'scenario'] }),
e.M('Holter application', 2, 'TRAP: For Holter monitoring, electrodes are placed:', 'Over bone (sternum and ribs) rather than large muscles, to reduce motion and muscle artifact', ['Over the pectoral and abdominal muscles for better signal', 'On the arms and legs as for a 12-lead', 'Only on the back'], 'Bony landmarks move less than muscle during daily activity, giving a cleaner 24–48-hour recording. Limb positions are used for resting 12-leads, not for ambulatory monitoring.', SRC.BOOTH, T),
e.M('Holter education', 2, 'TRAP: A patient wearing a standard Holter should be told to:', 'Avoid getting the recorder wet (no shower or bath) and keep the diary', ['Remove the monitor at night', 'Swim normally', 'Unplug lead wires during meals'], 'Most standard Holter recorders are not waterproof, and removing them interrupts the recording. Some newer patch monitors are water-resistant—follow the device instructions.', SRC.ISHNE, T),

// ===================== F: Rhythm analysis (58) =====================
// --- look-alike rhythms (with strips) ---
f.M('Atrial rhythms', 2, 'TRAP: This rhythm is irregular, like atrial fibrillation. Which feature shows it is MAT instead?', 'Distinct P waves with at least three different shapes before the QRS complexes', ['No P waves at all', 'Sawtooth flutter waves', 'Wide QRS complexes'], 'MAT has visible P waves of three or more morphologies with varying PR intervals at a rate over 100; AF has no organized P waves. Flutter waves are regular sawtooth waves.', SRC.DUBIN, TI('mat-3')),
f.M('Atrial rhythms', 3, 'TRAP: A regular narrow-complex rhythm at about 150 bpm (shown) should make you look carefully for:', 'Hidden flutter waves (atrial flutter with 2:1 conduction)', ['Delta waves', 'A long QT', 'Pacing spikes'], 'Flutter at about 300/min with 2:1 conduction gives a ventricular rate near 150; one flutter wave is often buried in the QRS or T wave. It is easily mislabeled as sinus tachycardia or SVT.', SRC.DUBIN, TI('aflutter-5')),
f.M('Heart blocks', 2, 'TRAP: How do you tell Mobitz I (Wenckebach) from Mobitz II?', 'Mobitz I: PR lengthens before the dropped beat; Mobitz II: PR stays constant before the dropped beat', ['Mobitz I has wide QRS complexes; Mobitz II never drops beats', 'Mobitz II has a progressively shortening PR', 'They cannot be distinguished on a strip'], 'Compare the PR interval of the beats before the non-conducted P wave. Progressive lengthening = Mobitz I; constant PR = Mobitz II, which is more dangerous and often has a wide QRS.', SRC.DUBIN, TI('mobitz1-3')),
f.M('Heart blocks', 3, 'TRAP: This strip shows every other P wave not conducted (2:1). Which statement is correct?', 'It cannot be labeled Mobitz I or Mobitz II from this strip alone, because no two consecutive PR intervals can be compared', ['It is always Mobitz II', 'It is always Wenckebach', 'It is third-degree block'], 'With 2:1 conduction there is never a pair of consecutive conducted beats to compare PRs, so call it "2:1 AV block." A longer strip or clinical context may reveal the type.', SRC.DUBIN, TI('avb21-3')),
f.M('Heart blocks', 3, 'TRAP: Which finding distinguishes third-degree AV block from Mobitz II?', 'In third-degree block the PR intervals vary randomly because P waves and QRS complexes are independent', ['In third-degree block the PR is constant', 'Third-degree block has more QRS complexes than P waves', 'Mobitz II has regular P waves "marching through" the QRS'], 'Complete heart block shows AV dissociation: P waves march at their own rate and QRS complexes at a slower, regular escape rate, so the PR keeps changing. In Mobitz II, conducted beats have a constant PR.', SRC.DUBIN, TI('avb3-3')),
f.M('Heart blocks', 2, 'TRAP: A constant PR interval of 0.26 s with every P wave conducted is:', 'First-degree AV block', ['Normal for an older adult', 'Mobitz I', 'Third-degree AV block'], 'A PR longer than 0.20 s with 1:1 conduction is first-degree AV block, regardless of age. No beats are dropped, so it is not second-degree, and the P waves are related to the QRS, so it is not third-degree.', SRC.DUBIN, TI('avb1-3')),
f.M('Junctional rhythms', 2, 'TRAP: This narrow-complex rhythm has inverted P waves in lead II with a PR < 0.12 s. It is NOT sinus because:', 'Inverted P waves with a short PR mean the impulse starts near the AV junction and travels backward to the atria', ['Sinus P waves are always inverted in lead II', 'The QRS is too wide', 'There are no P waves at all'], 'Sinus P waves are upright in lead II. A retrograde (inverted) P with a short PR, a hidden P, or a P after the QRS indicates a junctional origin.', SRC.DUBIN, TI('junctional-3')),
f.M('Junctional rhythms', 2, 'TRAP: A junctional rhythm at 80 bpm is called:', 'Accelerated junctional rhythm', ['Junctional escape rhythm', 'Junctional tachycardia', 'Sinus rhythm'], 'Junctional rates: escape 40–60, accelerated 60–100, tachycardia > 100 bpm. The P-wave pattern stays junctional, so it is not sinus.', SRC.DUBIN, TI('accjunct-3')),
f.M('Junctional rhythms', 2, 'TRAP: A junctional rhythm faster than 100 bpm is called:', 'Junctional tachycardia', ['Accelerated junctional rhythm', 'Sinus tachycardia', 'Ventricular tachycardia'], 'Above 100 bpm a junctional rhythm is junctional tachycardia; 60–100 is accelerated junctional. The narrow QRS and inverted/absent P waves distinguish it from sinus and ventricular rhythms.', SRC.DUBIN, TI('jtach-3')),
f.M('Ventricular rhythms', 2, 'TRAP: A regular wide-QRS rhythm at 70 bpm with no P waves (shown) is:', 'Accelerated idioventricular rhythm (AIVR)', ['Ventricular tachycardia', 'Idioventricular escape rhythm', 'Junctional rhythm'], 'Ventricular rhythms by rate: idioventricular 20–40, accelerated idioventricular about 40–100, VT > 100. AIVR is common after reperfusion and is usually not shocked.', SRC.DUBIN, TI('aivr-3')),
f.M('Ventricular rhythms', 2, 'TRAP: What separates an idioventricular rhythm from a junctional escape rhythm?', 'QRS width: idioventricular is wide (≥ 0.12 s) at 20–40 bpm; junctional is usually narrow at 40–60 bpm', ['Idioventricular has upright P waves before each QRS', 'Junctional rhythm is always wide', 'They have the same rate'], 'A ventricular focus spreads through muscle, giving a wide QRS and a slower intrinsic rate. Junctional impulses use the normal His-Purkinje system, so the QRS is usually narrow.', SRC.DUBIN, TI('idio-3')),
f.M('Ventricular rhythms', 3, 'TRAP: This polymorphic VT twists around the baseline. Why is it important to recognize it as torsades rather than "just VT"?', 'Torsades is linked to a long QT and is treated with IV magnesium (plus defibrillation if pulseless)', ['Torsades is benign and needs no treatment', 'Torsades is treated with adenosine', 'Torsades is always artifact'], 'Torsades de pointes is associated with QT prolongation from drugs or electrolytes, so magnesium and removing the cause are key. Adenosine is for regular narrow SVT; pulseless torsades is defibrillated.', SRC.ACLS, TI('torsades-3')),
f.M('Ventricular rhythms', 3, 'TRAP: A low-amplitude wavy line (shown) could be fine VF or asystole. What should you do before calling asystole?', 'Confirm in a second lead, check the gain and lead connections — and check the patient', ['Shock immediately without looking at another lead', 'Call it asystole and stop', 'Give adenosine'], 'Fine VF can look flat in one lead or at low gain; it is shockable, while asystole is not. Confirming in another lead and checking connections avoids a fatal mistake.', SRC.ACLS, TI('vfibfine-3')),
f.M('Ventricular rhythms', 2, 'TRAP: The monitor suddenly shows a flat line, but the patient is talking to you. The most likely cause is:', 'A loose or disconnected lead (artifact)', ['Asystole', 'Ventricular fibrillation', 'Third-degree AV block'], 'Treat the patient, not the monitor: a conscious patient cannot be in asystole. Check electrodes and cables. A truly flat line in an unresponsive patient needs CPR.', SRC.AHA_AMB, TI('art_loose-3')),
f.M('Artifact', 2, 'TRAP: Chaotic waves resembling VT appear, but normal QRS complexes continue "marching through" at the expected times (shown). This is:', 'Artifact (e.g., muscle tremor or movement)', ['Ventricular tachycardia', 'Ventricular fibrillation', 'Torsades de pointes'], 'If the underlying QRS complexes keep appearing on time through the disturbance, the heart rhythm has not changed. Check the patient and the electrodes before calling a lethal arrhythmia.', SRC.BOOTH, TI('art_tremor-5')),
f.M('Sinus rhythms', 2, 'TRAP: What distinguishes sinus arrhythmia from sinus arrest?', 'Sinus arrhythmia changes gradually with breathing; sinus arrest is a sudden pause with a missing P–QRS–T', ['Sinus arrhythmia has no P waves', 'Sinus arrest is always regular', 'They are the same rhythm'], 'In sinus arrhythmia the R–R gradually lengthens and shortens with respiration, and every beat is sinus. In sinus arrest the SA node fails to fire, producing an abrupt pause not equal to a multiple of the P–P interval.', SRC.DUBIN, TI('sinarr-3')),
f.M('Sinus rhythms', 2, 'TRAP: In sinus arrest, the length of the pause is typically:', 'Not an exact multiple of the normal P–P interval', ['Exactly two P–P intervals', 'Exactly three P–P intervals', 'Equal to one R–R interval'], 'Because the SA node actually stops and restarts, the pause is not a multiple of the P–P cycle. A pause that equals exactly two cycles suggests SA exit block.', SRC.DUBIN, TI('sarrest-3')),
f.M('Atrial rhythms', 2, 'TRAP: A premature beat with an upright but differently shaped P wave and a narrow QRS is a:', 'Premature atrial complex (PAC)', ['Premature junctional complex', 'Premature ventricular complex', 'Sinus arrest'], 'PACs have an early, abnormal-looking upright P wave. PJCs have an inverted, absent or retrograde P wave, and PVCs have a wide bizarre QRS with no preceding P.', SRC.DUBIN, TI('pac-3')),
f.M('Junctional rhythms', 2, 'TRAP: An early narrow beat with an inverted P wave just before the QRS (PR < 0.12 s) is a:', 'Premature junctional complex (PJC)', ['PAC', 'PVC', 'Blocked PAC'], 'The inverted P with a short PR shows retrograde atrial activation from the junction. A PAC has an upright (though abnormal) P, and a PVC is wide with no P wave.', SRC.DUBIN, TI('pjc-3')),
f.M('Ventricular rhythms', 2, 'TRAP: A PVC is usually followed by a full compensatory pause. This means:', 'The R–R interval spanning the PVC equals two normal R–R intervals', ['The next beat comes early', 'The pause is shorter than one R–R interval', 'The pacemaker fires'], 'The sinus node keeps its timing; the sinus P wave after the PVC is blocked, so the next beat comes on schedule two cycles later. PACs usually reset the sinus node (non-compensatory pause).', SRC.DUBIN, TI('pvc-3')),
f.M('Ventricular rhythms', 2, 'TRAP: Two normal beats then one PVC, repeating (shown), is:', 'Ventricular trigeminy', ['Ventricular bigeminy', 'A couplet', 'Ventricular tachycardia'], 'Trigeminy = every third beat is a PVC; bigeminy = every other beat. A couplet is two PVCs in a row, and three or more in a row is a run of VT.', SRC.DUBIN, TI('trigeminy-3')),
f.M('Ventricular rhythms', 2, 'TRAP: How many consecutive PVCs make a run of ventricular tachycardia?', 'Three or more', ['Two', 'One', 'Five or more'], 'Two PVCs in a row are a couplet (shown); three or more consecutive PVCs at a rate above 100 are a run of VT. Sustained VT lasts 30 seconds or more or causes instability.', SRC.DUBIN, TI('couplet-3')),
f.M('Ventricular rhythms', 2, 'TRAP: PVCs with different shapes on the same strip (shown) are called:', 'Multifocal PVCs', ['Unifocal PVCs', 'Aberrant PACs', 'Fusion beats only'], 'Different shapes mean the PVCs come from more than one ventricular focus. Unifocal PVCs all look alike.', SRC.DUBIN, TI('multifocal-3')),
f.M('Atrial rhythms', 2, 'TRAP: Wandering atrial pacemaker and MAT both have three or more P-wave shapes. What separates them?', 'Heart rate: WAP is under 100 bpm; MAT is over 100 bpm', ['WAP has no P waves', 'MAT has a regular rhythm', 'WAP has wide QRS complexes'], 'Both have varying P morphologies and PR intervals; the rate is the difference. Neither has absent P waves, and both are usually narrow and irregular.', SRC.DUBIN, TI('wap-3')),
f.M('Atrial rhythms', 2, 'TRAP: Which feature favors SVT over sinus tachycardia?', 'Abrupt onset at a rate usually over 150 bpm with P waves not visible', ['Gradual onset with upright P waves before each QRS', 'Rate of 105 bpm', 'Wide QRS complexes'], 'Sinus tachycardia speeds up and slows down gradually and has visible sinus P waves, usually ≤ 150 at rest. SVT starts and stops suddenly and P waves are often hidden.', SRC.DUBIN, TI('svt-3')),
f.M('Sinus rhythms', 2, 'TRAP: This rhythm at about 125 bpm has an upright P before every QRS and a normal PR. It is:', 'Sinus tachycardia', ['SVT', 'Atrial flutter', 'Junctional tachycardia'], 'Normal P–QRS relationships at > 100 bpm make it sinus tachycardia. SVT usually lacks visible P waves and is faster; flutter shows sawtooth waves; junctional P waves are inverted or absent.', SRC.DUBIN, TI('stach-3')),
f.M('Sinus rhythms', 2, 'TRAP: A slow rhythm under 60 bpm with upright P waves and a normal PR is sinus bradycardia, not junctional, because:', 'The P waves are upright in lead II and precede each QRS with a normal PR', ['The QRS is wide', 'There are no P waves', 'The P waves are inverted'], 'Rate alone does not make a rhythm junctional. Normal upright sinus P waves with PR 0.12–0.20 s at under 60 bpm is sinus bradycardia.', SRC.DUBIN, TI('sbrady-3')),
f.M('Ventricular rhythms', 3, 'TRAP: A wide-complex regular tachycardia of uncertain origin (shown) should be treated as:', 'Ventricular tachycardia until proven otherwise', ['SVT with aberrancy, so give verapamil', 'Sinus tachycardia', 'Artifact'], 'Most wide-complex tachycardias are VT, and treating VT as SVT (for example with calcium channel blockers) can cause collapse. Always check the patient for a pulse and stability.', SRC.ACLS, TI('vtach-3')),
f.M('Bundle branch block', 2, 'TRAP: A wide QRS that follows a normal P wave and PR interval on every beat (shown) is most likely:', 'Sinus rhythm with a bundle branch block', ['Ventricular tachycardia', 'Idioventricular rhythm', 'A run of PVCs'], 'A consistent P wave before each wide QRS with a normal PR shows the beats are conducted from the sinus node; the width comes from the bundle branch block. Ventricular rhythms have no related P waves.', SRC.AHA_BBB, TI('rbbb-3')),
f.M('Pacemakers', 2, 'TRAP: A pacing spike NOT followed by a P wave or QRS (shown) is:', 'Failure to capture', ['Failure to sense', 'Normal pacing', 'Oversensing'], 'Failure to capture means the pacemaker fires but the heart does not respond. Failure to sense (undersensing) means spikes appear despite intrinsic beats, often landing on them.', SRC.ACC_PACE, TI('failcapture-3')),
f.M('Pacemakers', 2, 'TRAP: Pacing spikes that land on or right after the patient\'s own QRS complexes (shown) indicate:', 'Failure to sense (undersensing)', ['Failure to capture', 'Normal demand pacing', 'Atrial fibrillation'], 'A demand pacemaker should be inhibited by the patient\'s own beats. Spikes that ignore intrinsic beats show it is not sensing them, which risks R-on-T. Failure to capture is a spike with no response.', SRC.ACC_PACE, TI('failsense-3')),
f.M('Pacemakers', 2, 'TRAP: Two pacing spikes per beat — one before the P wave and one before the wide QRS (shown) — indicate:', 'Dual-chamber (AV) pacing', ['Atrial pacing only', 'Ventricular pacing only', 'Failure to capture'], 'An atrial spike followed by a P wave and a ventricular spike followed by a wide QRS is AV sequential pacing. Atrial-only pacing has one spike before the P and a normal QRS.', SRC.ACC_PACE, TI('avpace-3')),
f.M('Atrial rhythms', 2, 'TRAP: Why is it a mistake to call this irregularly irregular rhythm "atrial flutter"?', 'There are no regular sawtooth flutter waves — only a chaotic fibrillatory baseline (atrial fibrillation)', ['Because the QRS is wide', 'Because the rate is under 60', 'Because there are clear upright P waves'], 'Flutter has organized, regular sawtooth waves and usually a regular (or regularly varying) ventricular response. AF has a disorganized baseline with an irregularly irregular R–R interval.', SRC.DUBIN, TI('afib-3')),
// --- intervals & waveforms (reference strips) ---
f.M('Intervals & waveforms', 2, 'TRAP: The PR interval is measured from the:', 'Start of the P wave to the start of the QRS complex', ['Peak of the P wave to the peak of the R wave', 'End of the P wave to the start of the QRS', 'Start of the P wave to the end of the T wave'], 'PR = beginning of P to beginning of QRS (normal 0.12–0.20 s). The end-of-P to QRS portion is the PR segment, which is used as the baseline, not the interval.', SRC.AHA_STD, TI('nsr-1')),
f.M('Intervals & waveforms', 2, 'TRAP: The QT interval is measured from the:', 'Start of the QRS complex to the end of the T wave', ['Start of the P wave to the end of the T wave', 'Peak of the R wave to the peak of the T wave', 'End of the QRS to the start of the T wave'], 'QT includes ventricular depolarization and repolarization; it varies with heart rate, so it is corrected (QTc). The end-of-QRS to T portion is the ST segment.', SRC.AHA_QT, TI('nsr-2')),
f.M('Intervals & waveforms', 2, 'TRAP: A QRS duration of 0.12 s is:', 'Wide (abnormal)', ['Normal', 'Short', 'Normal only in children'], 'A normal adult QRS is less than 0.12 s (about 0.06–0.10 s). At 0.12 s or more, suspect bundle branch block, a ventricular rhythm, pacing or pre-excitation.', SRC.AHA_BBB, TI('lbbb-4')),
f.M('Intervals & waveforms', 2, 'TRAP: On ECG paper at 25 mm/s, one large (5 mm) box equals:', '0.20 second', ['0.04 second', '0.5 second', '1 second'], 'One small box = 0.04 s, one large box = 0.20 s, five large boxes = 1 second. A 6-second strip contains 30 large boxes.', SRC.AHA_STD, TI('nsr-3')),
f.M('Intervals & waveforms', 3, 'TRAP: QT = 0.40 s and the R–R interval = 0.64 s. What is the QTc (Bazett)?', '0.50 s', ['0.40 s', '0.63 s', '0.26 s'], 'QTc = QT ÷ √RR = 0.40 ÷ √0.64 = 0.40 ÷ 0.8 = 0.50 s, which is prolonged. Forgetting the square root (0.40 ÷ 0.64 ≈ 0.63) is the classic error, and the RR must be in seconds.', SRC.AHA_QT, TC('nsr-4')),
f.M('Intervals & waveforms', 2, 'TRAP: At a heart rate of exactly 60 bpm, the QTc equals:', 'The measured QT', ['Twice the measured QT', 'Half the measured QT', 'Zero'], 'At 60 bpm the R–R interval is 1.0 s, and √1 = 1, so QTc = QT. At faster rates the correction lengthens the value; at slower rates it shortens it.', SRC.AHA_QT, TC('nsr-5')),
f.M('Intervals & waveforms', 2, 'TRAP: A U wave is:', 'A small wave after the T wave, prominent in hypokalemia', ['Atrial repolarization', 'Part of the QRS', 'A pacing spike'], 'U waves follow the T wave and become prominent with low potassium (and some drugs). Atrial repolarization is usually hidden in the QRS.', SRC.AHA_QT, TI('nsr-6')),
f.M('Rate calculation', 2, 'TRAP: There are 20 small boxes between R waves on a regular rhythm. The heart rate is:', '75 bpm', ['15 bpm', '150 bpm', '60 bpm'], '1500 ÷ small boxes = 1500 ÷ 20 = 75 bpm. Using 300 ÷ 20 (= 15) applies the large-box method to small boxes, a common error.', SRC.DUBIN, TC('nsr-7')),
f.M('Rate calculation', 2, 'TRAP: Which rate method should you use for an irregular rhythm such as atrial fibrillation?', 'Count the QRS complexes in a 6-second strip and multiply by 10', ['1500 ÷ small boxes between two R waves', '300 ÷ large boxes between two R waves', 'Measure the PR interval and multiply by 100'], 'The 300 and 1500 methods need a regular R–R interval; on an irregular rhythm they give a different answer for every pair of beats. The 6-second method averages the rate.', SRC.DUBIN, TC('afib-4')),
f.M('Rate calculation', 1, 'TRAP: In the 300 (sequence) method, what heart rates go with 1, 2, 3, 4, 5 and 6 large boxes?', '300, 150, 100, 75, 60, 50', ['300, 200, 100, 50, 25, 10', '150, 100, 75, 60, 50, 40', '60, 70, 80, 90, 100, 110'], 'Rate = 300 ÷ number of large boxes between R waves: 300, 150, 100, 75, 60, 50. Memorizing this sequence gives a quick estimate on regular rhythms.', SRC.DUBIN, TC('nsr-8')),
f.M('Rate calculation', 3, 'TRAP: In third-degree AV block (shown), how should you report the rate?', 'Report the atrial and ventricular rates separately', ['Report only the P-wave rate', 'Average the P and QRS rates', 'Rate cannot be calculated'], 'In AV dissociation the atria and ventricles beat independently, so give both (for example, atrial 90, ventricular 40). Averaging them describes neither chamber.', SRC.DUBIN, TC('avb3-4')),
// --- medications (8) ---
f.M('Medications', 2, 'TRAP: Scooped ("Salvador Dalí") ST depression in a patient on digoxin means:', 'Digoxin effect — expected and not by itself toxicity', ['Digoxin toxicity requiring an antidote', 'Acute STEMI', 'Hyperkalemia'], 'Therapeutic digoxin causes sagging ST segments and a short QT. Toxicity is suggested by new arrhythmias (PAT with block, AV block, PVCs, bidirectional VT) and symptoms such as nausea or visual changes.', SRC.FDA, TM),
f.M('Medications', 2, 'TRAP: A drug name ending in "-olol" (such as metoprolol) belongs to which class, and what does it do to the ECG?', 'Beta blocker — slows heart rate and can lengthen the PR interval', ['ACE inhibitor — widens the QRS', 'Calcium channel blocker — causes U waves', 'Diuretic — causes peaked T waves'], 'Beta blockers slow SA-node firing and AV conduction. "-pril" drugs are ACE inhibitors, and diuretic ECG effects come from the electrolyte changes they cause.', SRC.FDA, TM),
f.M('Medications', 2, 'TRAP: Amiodarone and sotalol are monitored on the ECG mainly for:', 'QT prolongation (risk of torsades de pointes)', ['QRS narrowing', 'Peaked T waves', 'Short PR intervals'], 'Class III antiarrhythmics prolong repolarization, lengthening the QT interval. Excessive QT prolongation raises the risk of torsades, which is treated with magnesium.', SRC.FDA, TM),
f.M('Medications', 3, 'TRAP: After rapid IV adenosine for SVT, the monitor shows a few seconds of asystole before sinus rhythm returns. This is:', 'An expected, brief effect of adenosine blocking the AV node', ['A sign the patient needs immediate defibrillation', 'An allergic reaction', 'Lead reversal'], 'Adenosine has a half-life of seconds and transiently blocks the AV node, often producing a short pause before the rhythm recovers. Persistent asystole with no pulse would require CPR.', SRC.ACLS, TM),
f.M('Medications', 2, 'TRAP: The first-line drug for symptomatic sinus bradycardia in ACLS is:', 'Atropine 1 mg IV (repeat every 3–5 minutes, maximum 3 mg)', ['Adenosine 6 mg rapid IV push', 'Amiodarone 300 mg', 'Metoprolol 5 mg IV'], 'AHA 2020 ACLS uses atropine 1 mg as the first drug for symptomatic bradycardia, followed by pacing or dopamine/epinephrine infusions if ineffective. Adenosine is for SVT, and amiodarone and metoprolol would slow the rate further or treat other rhythms.', SRC.ACLS, TM),
f.M('Medications', 2, 'TRAP: Which drug is given for torsades de pointes?', 'Magnesium sulfate', ['Adenosine', 'Digoxin', 'Atropine'], 'IV magnesium stabilizes the myocardium in torsades associated with a long QT. Adenosine is for SVT, digoxin slows AV conduction, and atropine treats bradycardia.', SRC.ACLS, TM),
f.M('Medications', 3, 'TRAP: Which calcium channel blocker has little effect on AV conduction?', 'Amlodipine (a dihydropyridine)', ['Diltiazem', 'Verapamil', 'All calcium channel blockers slow the AV node equally'], 'Dihydropyridines ("-dipine") mainly dilate arteries and lower BP. Diltiazem and verapamil slow the SA and AV nodes and are used for rate control in AF/flutter.', SRC.FDA, TM),
// --- life-threatening & reporting (4) ---
f.M('Life-threatening', 2, 'TRAP: Pulseless ventricular tachycardia is treated like:', 'Ventricular fibrillation — CPR and immediate defibrillation', ['Stable VT — synchronized cardioversion only', 'Asystole — epinephrine without shocks', 'SVT — adenosine'], 'Pulseless VT and VF are the two shockable arrest rhythms in ACLS. Synchronized cardioversion is for unstable VT with a pulse, and asystole/PEA are not shocked.', SRC.ACLS, TI('vtach-4')),
f.M('Life-threatening', 3, 'TRAP: The monitor shows an organized sinus rhythm, but the patient is unresponsive with no pulse. This is:', 'Pulseless electrical activity (PEA) — start CPR; do not shock', ['Normal sinus rhythm — no action needed', 'VF — defibrillate', 'Artifact — ignore it'], 'PEA is any organized rhythm without a pulse; treatment is CPR, epinephrine and finding the cause. It is not shockable. The monitor never replaces a pulse check.', SRC.ACLS, TI('nsr-9')),
f.M('Life-threatening', 2, 'TRAP: Which rhythm is NOT shockable?', 'Asystole', ['Ventricular fibrillation', 'Pulseless ventricular tachycardia', 'Torsades de pointes without a pulse'], 'Asystole has no electrical activity to reset, so it is treated with CPR and epinephrine. VF, pulseless VT and pulseless torsades are defibrillated.', SRC.ACLS, TI('asystole-4')),
f.M('Report & communicate', 2, 'TRAP: You record a new Mobitz II block on an outpatient ECG. What should you do?', 'Report it promptly to the nurse or physician per the facility\'s critical-result policy, and stay with the patient', ['Put the tracing in the routine reading pile', 'Tell the patient they need a pacemaker', 'Repeat the ECG tomorrow'], 'Mobitz II can progress suddenly to complete heart block, so it is reported right away. Technicians communicate findings to the care team; they do not give diagnoses or treatment plans to patients.', SRC.ACC_PACE, TI('mobitz2-3')),
];
